def longest(a: list[int], b: list[int]) -> list[int]:
    """Return the longer of a and b; on a tie, return a."""
    return b if len(b) > len(a) else a


def test_longer_second_list_wins() -> None:
    assert longest([1], [2, 3]) == [2, 3]


def test_longer_first_list_wins() -> None:
    assert longest([1, 2], [3]) == [1, 2]


def test_tie_returns_first() -> None:
    assert longest([1, 2], [3, 4]) == [1, 2]


def test_empty_lists() -> None:
    assert longest([], []) == []
    assert longest([], [9]) == [9]
    assert longest([9], []) == [9]
